// COMPILED REGRESSION TEST — generated by the test compiler from a
// successful exploration trace. Deterministic: no agent, no planner,
// no LLM at replay time. Do not edit by hand; recompile instead.
// Flow: login — Sign in with the demo account and confirm the product list is shown
// Explored with driver=playwright, provider=deterministic, at 2026-10-13T05:53:28.773Z.
import { createDriver } from "../src/driver/driver.mjs";

const APP_URL = process.env.QA_APP_URL;
if (!APP_URL) fail("environment", "QA_APP_URL env var not set");

function matchDescriptor(elements, spec) {
  if (!spec) return [];
  if (spec.testId) {
    const m = elements.filter((e) => e.testId === spec.testId);
    if (m.length) return m;
  }
  if (spec.role && spec.name) {
    const target = String(spec.name).toLowerCase();
    const m = elements.filter((e) => e.role === spec.role && (e.name || "").toLowerCase() === target);
    if (m.length) return m;
  }
  if (spec.text) {
    const m = elements.filter((e) => e.text === spec.text);
    if (m.length) return m;
  }
  if (spec.css && spec.id) return elements.filter((e) => e.id === spec.id);
  return [];
}

function evaluateAssertion(a, snapshot) {
  switch (a.kind) {
    case "element": {
      const m = matchDescriptor(snapshot.elements, a.find).filter((e) => e.visible);
      if (!m.length) return { pass: false, matchedAny: false, detail: "element not found/visible: " + JSON.stringify(a.find) };
      if (a.textContains && !m[0].text.includes(a.textContains))
        return { pass: false, matchedAny: true, detail: "element text \"" + m[0].text + "\" does not contain \"" + a.textContains + "\"" };
      return { pass: true, matchedAny: true, detail: "element present" };
    }
    case "elementAbsent": {
      const m = matchDescriptor(snapshot.elements, a.find).filter((e) => e.visible);
      return m.length
        ? { pass: false, matchedAny: true, detail: "element unexpectedly present: " + JSON.stringify(a.find) }
        : { pass: true, matchedAny: false, detail: "element absent as expected" };
    }
    case "elementText": {
      const m = matchDescriptor(snapshot.elements, a.find);
      if (!m.length) return { pass: false, matchedAny: false, detail: "element not found: " + JSON.stringify(a.find) };
      const ok = a.equals !== undefined ? m[0].text === a.equals : m[0].text.includes(a.contains || "");
      return { pass: ok, matchedAny: true, detail: "element text \"" + m[0].text + "\"" };
    }
    case "text": {
      const ok = snapshot.pageText.includes(a.text);
      return { pass: ok, matchedAny: true, detail: ok ? "page contains text" : "page missing text \"" + a.text + "\"" };
    }
    case "view": {
      const ok = snapshot.hash === a.hash;
      return { pass: ok, matchedAny: true, detail: "hash " + snapshot.hash + " vs expected " + a.hash };
    }
    default:
      return { pass: false, matchedAny: true, detail: "unknown assertion kind " + a.kind };
  }
}

async function waitForAssertion(driver, assertion, timeoutMs) {
  const start = Date.now();
  let last = { pass: false, matchedAny: false, detail: "no snapshot taken" };
  while (Date.now() - start < (timeoutMs || 6000)) {
    const snap = await driver.snapshot();
    last = evaluateAssertion(assertion, snap);
    if (last.pass) return last;
    await new Promise((r) => setTimeout(r, 100));
  }
  return last;
}

// Diagnostics about how this run's own actions grounded. An act "drifted"
// when its recorded spec carried a testId but a fallback strategy had to be
// used instead — evidence the page surface has shifted under the test. The
// failure classifier uses this to tell a missing behavior on an intact page
// (product bug) from a generally drifted page (test rot).
const ACT_LOG = [];
function actDiagnostics() {
  const drifted = ACT_LOG.filter((a) => a.hadTestId && a.strategy !== "testid").length;
  return { total: ACT_LOG.length, drifted: drifted };
}

function fail(phase, detail, extra) {
  console.log("QA_RESULT " + JSON.stringify(Object.assign({ status: "fail", phase: phase, detail: detail }, extra || {})));
  process.exit(1);
}


async function main() {
  let driver;
  try {
    driver = await createDriver({ origin: new URL(APP_URL).origin });
  } catch (e) { fail("environment", "driver start failed: " + String(e && e.message || e)); }
  try {
    await driver.goto(APP_URL);
    // step 1: Enter the demo account email (exploration grounded via "testid")
    {
      const res = await driver.act({"testId":"login-email","role":"textbox","name":"Email","css":"main > section > form > label:nth-of-type(1) > input"}, {"kind":"fill","value":"ada@example.com"});
      if (!res.ok) fail(res.phase || "grounding", "step 1 action failed", { grounding: res.strategies || [] });
      ACT_LOG.push({ hadTestId: true, strategy: res.strategy });
      await driver.waitForQuiescence();
    }
    // step 2: Enter the demo account password (exploration grounded via "testid")
    {
      const res = await driver.act({"testId":"login-password","role":"textbox","name":"Password","css":"main > section > form > label:nth-of-type(2) > input"}, {"kind":"fill","value":"password123"});
      if (!res.ok) fail(res.phase || "grounding", "step 2 action failed", { grounding: res.strategies || [] });
      ACT_LOG.push({ hadTestId: true, strategy: res.strategy });
      await driver.waitForQuiescence();
    }
    // step 3: Submit the sign-in form (exploration grounded via "testid")
    {
      const res = await driver.act({"testId":"login-submit","role":"button","name":"Sign in","text":"Sign in","css":"main > section > form > button"}, {"kind":"click"});
      if (!res.ok) fail(res.phase || "grounding", "step 3 action failed", { grounding: res.strategies || [] });
      ACT_LOG.push({ hadTestId: true, strategy: res.strategy });
      await driver.waitForQuiescence();
    }
    // final assertions (from exploration verdict)
    {
      const r = await waitForAssertion(driver, {"kind":"view","hash":"#/products"});
      if (!r.pass) {
        fail("assertion", r.detail, { assertion: {"kind":"view","hash":"#/products"}, matchedAny: r.matchedAny, acts: actDiagnostics() });
      }
    }
    {
      const r = await waitForAssertion(driver, {"kind":"element","find":{"testId":"product-grid"}});
      if (!r.pass) {
        fail("assertion", r.detail, { assertion: {"kind":"element","find":{"testId":"product-grid"}}, matchedAny: r.matchedAny, acts: actDiagnostics() });
      }
    }
    console.log('QA_RESULT {"status":"pass"}');
    await driver.close();
  } catch (e) {
    if (e && (e.code === "ENVIRONMENT" || e.code === "ORIGIN_BLOCKED")) fail("environment", String(e.message || e));
    fail("environment", "unexpected error: " + String(e && e.message || e));
  }
}
main();
